import pyomo.environ as pyo

DATA = {
    "routes": [1, 2, 3, 4],
    "cost": {1: 10, 2: 9, 3: 11, 4: 12},
    "upper_pairs": {
        (1, 2): 500,   # x1 + x2 <= 500
        (3, 4): 400,   # x3 + x4 <= 400
    },
    "lower_pairs": {
        (1, 3): 300,   # x1 + x3 >= 300
        (2, 4): 600,   # x2 + x4 >= 600
    },
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.R = pyo.Set(initialize=d["routes"])
    model.U = pyo.Set(initialize=list(d["upper_pairs"].keys()), dimen=2)
    model.L = pyo.Set(initialize=list(d["lower_pairs"].keys()), dimen=2)

    model.x = pyo.Var(model.R, within=pyo.NonNegativeIntegers)

    def obj_rule(m):
        return sum(d["cost"][r] * m.x[r] for r in m.R)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def upper_rule(m, i, j):
        return m.x[i] + m.x[j] <= d["upper_pairs"][(i, j)]

    model.upper = pyo.Constraint(model.U, rule=upper_rule)

    def lower_rule(m, i, j):
        return m.x[i] + m.x[j] >= d["lower_pairs"][(i, j)]

    model.lower = pyo.Constraint(model.L, rule=lower_rule)

    return model


